nodes.statement:
In this paper, we consider a networked system consisting of $n$ nodes (agents) that collectively solve the following nonconvex-strongly-convex bilevel optimization problem:
\vspace{-0.23cm}
\begin{equation} \begin{aligned}
    \min_{x \in \mathbb{R}^p} &\Phi(x) = f(x, y^*(x)) := \frac{1}{n} \sum_{i=1}^n f_i(x, y^*(x)), \\
    \text{s.t.} ~~& y^*(x) = \arg\min_{y \in \mathbb{R}^q} l(x, y) :=  \frac{1}{n} \sum_{i=1}^n l_i(x, y),
\end{aligned}
\end{equation}
where $f(\cdot)$ represents the upper-level objective function, which is minimized with respect to $x$, subject to the constraint that $y^*(x)$ is a minimizer of the lower-level function $l(\cdot)$.

\begin{aligned}
    \min_{x \in \mathbb{R}^p} &\Phi(x) = f(x, y^*(x)) := \frac{1}{n} \sum_{i=1}^n f_i(x, y^*(x)), \\
    \text{s.t.} ~~& y^*(x) = \arg\min_{y \in \mathbb{R}^q} l(x, y) :=  \frac{1}{n} \sum_{i=1}^n l_i(x, y),
\end{aligned}

A key challenge in solving the Problem \eqref{eqcontent1} is the computation of the hypergradient $
abla \Phi(x)$, which is expressed as:
{\setlength{\abovedisplayskip}{3pt}
\setlength{ elowdisplayskip}{5pt}
 egin{equation}  egin{aligned}

abla \Phi(x) :=
abla_x f(x, y^*(x)) - 
abla_{x}
abla_{y} l(x, y^*(x)) [
abla_{y}
abla_{y} l(x, y^*(x))]^{-1} 
abla_y f(x, y^*(x)),
\end{aligned}
\end{equation}}derived using the implicit function theorem \citep{ghadimi2018approximation}.

 egin{aligned}

abla \Phi(x) :=
abla_x f(x, y^*(x)) - 
abla_{x}
abla_{y} l(x, y^*(x)) [
abla_{y}
abla_{y} l(x, y^*(x))]^{-1} 
abla_y f(x, y^*(x)),
\end{aligned}

To overcome this challenge, we introduce the following linear system:
{\setlength{\abovedisplayskip}{3pt}
\setlength{ elowdisplayskip}{3pt}
 egin{equation} \min_{v} r(x, \hat{y}, v) :=  rac{1}{2} v^	op 
abla_y
abla_y l(x, \hat{y}) v \!-\! v^	op 
abla_y f(x, \hat{y}),
\end{equation}}which seeks to approximate the inversion of the Hessian matrix by $ v^*(x)= [
abla_{y}
abla_{y} l(x, y^*(x))]^{-1} 
abla_y f(x, y^*(x))$ when $\hat{y}$ approaching $y^*(x)$, where $v\in\mathcal{V}$.

Using the approximations $\hat{y}$ and $\hat{v}$, the $x$ is subsequently updated based on a hypergradient estimate as:
{\setlength{\abovedisplayskip}{7pt}
\setlength{\belowdisplayskip}{2.5pt}
\begin{equation} \bar{\nabla} f(x, \hat{y}, \hat{v}) := \nabla_x f(x, \hat{y}) - \nabla_x \nabla_y l(x, \hat{y}) \hat{v}.
\end{equation}

Building on this framework, solving the decentralized bilevel optimization problem \eqref{eqcontent1} can be reformulated into three interconnected subproblems:
\begin{subequations} \vspace{-0.5cm}
\begin{center}
\begin{tabular}{@{}c@{\quad}c@{}}
  \begin{minipage}{0.45\textwidth}
    \begin{equation}
    x^* = \arg\min_{x \in \mathbb{R}^p} \frac{1}{n} \sum_{i=1}^n f_i(x, y^*(x),\tag{5a} \end{equation}
  \end{minipage}
  &
  \begin{minipage}{0.45\textwidth}
    \begin{equation}
    y^*(x) = \arg\min_{y \in \mathbb{R}^q} \frac{1}{n} \sum_{i=1}^n l_i(x, y), \tag{5b} \end{equation}
  \end{minipage}
\end{tabular}
\end{center}
\vspace{-0.4cm}
\begin{equation}
v^*(x) = \arg\min_{v \in \mathbb{R}^q} \frac{1}{n} \sum_{i=1}^n r_i(x, y^*(x), v). \quad\quad\!\!\!\text{(5c)} \notag
\end{equation}
\vspace{-0.4cm}
\end{subequations}

According to Problem \eqref{eqcontent4}, the local gradients at each agent $i$ can be expressed as:
 egin{equation*}
 ar{
abla}f_i(x_{i,t}, y_{i,t}, v_{i,t}) = 
abla_{x} f_i(x_{i,t}, y_{i,t}) - 
abla_{x}
abla_{y} l_i(x_{i,t}, y_{i,t}) v_{i,t},
\end{equation*}
 egin{equation*}

abla_{v} r_i(x_{i,t}, y_{i,t}, v_{i,t}) = 
abla_{y}
abla_{y} l_i(x_{i,t}, y_{i,t}) v_{i,t} -
abla_{y} f_i(x_{i,t}, y_{i,t}).
\end{equation*}

Correspondingly, we define the following diagonal stepsize matrices as: 
{\setlength{\abovedisplayskip}{2pt}
\setlength{\belowdisplayskip}{1pt}
\begin{equation*} Q_{t+1} = \text{diag} \big\{q_{i,t+1}\big\}_{i=1}^n, \quad 
U_{t+1} = \text{diag} \big\{u_{i,t+1}\big\}_{i=1}^n,\quad Z_{t+1}= \text{diag} \big\{z_{i,t+1}\big\}_{i=1}^n.\nonumber
\end{equation*}

We also concatenate the gradient vectors as:
{\setlength{\abovedisplayskip}{3pt}
\setlength{\belowdisplayskip}{2pt}
\begin{equation*}
    \bar{\nabla} {F}(\mathbf{x}_t, \mathbf{y}_t, \mathbf{v}_t) :=
    \begin{bmatrix}
         \cdots, \bar{\nabla}f_i(x_{i,t}, y_{i,t}, v_{i,t}),\cdots
    \end{bmatrix}^\top,\quad
    \nabla_y {L}(\mathbf{x}_t, \mathbf{y}_t) :=
    \begin{bmatrix}
        \cdots,  \nabla_yl_i(x_{i,t}, y_{i,t}),\cdots
    \end{bmatrix}^\top,
\end{equation*}
\begin{equation*}
    \!\nabla_v {R}(\mathbf{x}_t, \mathbf{y}_t, \mathbf{v}_t) =
    \begin{bmatrix}
        \cdots,\nabla_v r_i(x_{i,t}, y_{i,t}, v_{i,t}),\cdots
    \end{bmatrix}^\top.
\end{equation*}

Based on these definitions, the update rules for the primal, dual, and auxiliary variables are given by:
\begin{equation*}
\mathbf{x}_{t+1} = W \Big(\mathbf{x}_t - \gamma_x Q_{t+1}^{-1} \bar{\nabla} F(\mathbf{x}_t, \mathbf{y}_t,\mathbf{v}_t)\Big), \quad
\mathbf{y}_{t+1} = W \big(\mathbf{y}_t - \gamma_y U_{t+1}^{-1} \nabla_y L(\mathbf{x}_t, \mathbf{y}_t)\big),
\end{equation*}
\begin{equation*}
\mathbf{v}_{t+1} = \mathcal{P}_{\mathcal{V}}\Big(W \big(\mathbf{v}_t - \gamma_v Z_{t+1}^{-1} \nabla_v R(\mathbf{x}_t, \mathbf{y}_t,\mathbf{v}_t)\big)\Big),
\end{equation*}
where $\mathcal{P}_{\mathcal{V}}(\cdot)$ denotes the projection operation onto the set $\mathcal{V}$.

At each iteration, the gradient-norm accumulators $m^x_{i,t}$, $m^y_{i,t}$, and $m^v_{i,t}$ are tracked by:  
\begin{align*}
[m^b_{i,t+1}]^2 = \sum_{j=1}^n w_{ij}[m^b_{j,t+1}]^2 = \sum_{j=1}^n w_{ij} \left([m^b_{j,t}]^2 + \|g^b_{j,t}\|^2 \right)\!,
\end{align*}
where $b \in \{x, y, v\}$ and $i \in [n]$.

Suppose Assumptions ef{Assumption3}, ef{Assumption1}, and ef{Assumption2} hold. Define discrepancy vectors as \(	ilde{\mathbf{q}}_t^{-1} \!\!:=\!\!  ig[ \!\cdots, q_{i,t}^{-1}\!\! -\!\!  ar{q}_t^{-1}, \cdots \! ig]^	op\), \(	ilde{\mathbf{u}}_t^{-1} \!\!:=\!\!  ig[ \!\cdots, u_{i,t}^{-1}\!\! -\!\!  ar{u}_t^{-1}, \cdots \! ig]^	op\), and \(	ilde{\mathbf{z}}_t^{-1} \!\!:=\!\!  ig[ \!\cdots, z_{i,t}^{-1}\!\! -\!\!  ar{z}_t^{-1}, \cdots \! ig]^	op\). Then, under Algorithm~ef{alg1}, we have that
$ rac{1}{T}\sum_{t=0}^{T-1} \left\| { ig(	ilde{\mathbf{q}}_{t+1}^{-1} ig)^{	op}}  ar{
