abla}_y L(\mathbf{x}_t, \mathbf{y}_t)/{n ar{u}_{t+1}^{-1}} ight\|^2$, and $ rac{1}{T}\sum_{t=0}^{T-1} \left\| { ig(	ilde{\mathbf{z}}_{t+1}^{-1} ig)^	op} 
abla_v R(\mathbf{x}_t, \mathbf{y}_t, \mathbf{v}_t) /n ar{z}_{t+1}^{-1}ight\|^2$ are each upper-bounded by $\mathcal{O}\left({\log(T)}/{T}ight)$.

Under Assumptions \ref{Assumption3}, \ref{Assumption1}, and \ref{Assumption2}, for any positive constants $\gamma_x$, $\gamma_y$, $\gamma_v$, $m^x_{i,0}$,  $m^y_{i,0}$, and $m^v_{i,0}$, the iterates generated by \cref{alg1} satisfy:
\vspace{-0.19cm}
\begin{equation*}
\begin{aligned}
\frac{1}{T} \sum_{t=0}^{T-1} \|\nabla \Phi(\bar{x}_t)\|^2
&{\leq} \frac{2}{T}\!\Bigg[\!\!\left(\!{4}\!\left(\!\frac{\Phi(\bar{x}_0)\!-\!\Phi^*}{\gamma_x}\!\right)\!\!+\!a_7\log(T)\!\!+\!b_7\!\right)^{\!2}\!\!\!{(a_1\!\log(T) \!+\! b_1)^2}  \\
& \quad+ \!C_{m^x} \!\!\left(\!{4}\!\left(\!\frac{\Phi(\bar{x}_0)\!-\!\Phi^*}{\gamma_x}\!\right)\!\!+\!a_7\!\log(T)\!\!+\!b_7\!\right)\!(a_1\!\log(T)\!\!+\! b_1)\Bigg] \!=\! \mathcal{O}\left(\frac{\log^4(T)}{T}\right),
\end{aligned}
\end{equation*}
where $\Phi^* := \inf_{x \in \mathbb{R}^p} \Phi(x) > -\infty$, and the constants $C_{m^x}$, $a_1$, $b_1$, $a_7$, and $b_7$ are defined in Eqs.~\eqref{eq52}, \eqref{eq84}, and \eqref{eq128} in the Appendix.

For any non-negative $a_1, \dots, a_T,$ and $a_1 \geq 1$, we have:
\begin{align}
\sum_{l=1}^T \frac{a_l}{\sum_{i=1}^l a_i} \leq \log \left(\sum_{l=1}^T a_l\right) + 1. \end{align}

Under \cref{Assumption1} and \cref{Assumption2}, we have the following basic properties:
\begin{enumerate}
    \item[1).] \(\Phi(\bar{x})\) is \(L_{\Phi}\)-smooth with respect to \(\bar{x}\), where 
    $L_{\Phi} := \left(L_{f,1} + \frac{L_{l,2} C_{f_y}}{\mu} \right)\left(1 + \frac{C_{l_{xy}}}{\mu}\right)^2$;
    \item[2).] \({y}^*(\bar{x})\) is \(L_y\)-Lipschitz continuous with respect to \(\bar{x}\), where $L_y := \frac{C_{l_{xy}}}{\mu}$;
    \item[3).] The gradient estimator \(\bar{\nabla} f(\bar{x}, \bar{y}, \bar{v})\) is \((L_{l,2} \|\bar{v}\| + L_{f,1})\)-Lipschitz continuous with respect to \((\bar{x}, \bar{y})\) and \(L_{l,1}\)-Lipschitz continuous with respect to \(\bar{v}\);
    \item[4).] \(\bar{\nabla} f(\bar{x}, \bar{y}, \bar{v})\) can be bounded as $\|\bar{\nabla} f(\bar{x}, \bar{y}, \bar{v})\| \leq C_{l_{xy}} \|\bar{v}\| + C_{f_x}.$
\end{enumerate}

