&\leq\| (W - \mathbf{J}) ( \mathbf{m}_{k}^x-\mathbf{1}\bar{m}_{k}^x)\|^2 + \|(W - \mathbf{J}) \mathbf{g}_k^x \|^2  \notag \\
&\leq \frac{1 + \rho_W}{2} 
\| \mathbf{m}_k^x - \mathbf{1}\bar{m}_k^x \|^2 
+ \frac{(1 + \rho_W) \rho_W}{1 - \rho_W} \| \mathbf{g}_k^x \|^2 \notag \\
&\overset{(a)}{\leq} 
\left( \frac{1 + \rho_W}{2} \right)^k 
\| \mathbf{m}_0^x - \mathbf{1}\bar{m}_0^x \|^2 
+ \frac{n (1 + \rho_W) \rho_W}{(1 - \rho_W)^2}\left(\frac{C_{l_{xy}}C_{f_y}}{\mu}+C_{f_x}\right)^2 
\sum_{t=0}^k 
\left( \frac{1 + \rho_W}{2} \right)^{k-t} \notag \\
&\leq \frac{2n (1 + \rho_W) \rho_W}{(1 - \rho_W)^2}\left(\frac{C_{l_{xy}}C_{f_y}}{\mu}+C_{f_x}\right)^2, \end{align}
where (a) uses \cref{Lemma2}. For $\left\| \mathbf{m}_{k+1}^y-\mathbf{1}\bar{m}_{k+1}^y\right\|^2$, we have:
\begin{align}
&\left\| \mathbf{m}_{k+1}^y-\mathbf{1}\bar{m}_{k+1}^y\right\|^2\notag\\
&\leq\| (W - \mathbf{J}) ( \mathbf{m}_{k}^y-\mathbf{1}\bar{m}_{k}^y)\|^2 +  \|(W - \mathbf{J}) \mathbf{g}_k^y \|^2  \notag \\
&\leq \frac{1 + \rho_W}{2} 
\| \mathbf{m}_k^y - \mathbf{1}\bar{m}_k^y \|^2 
+ \frac{(1 + \rho_W) \rho_W}{1 - \rho_W} \| \mathbf{g}_k^y \|^2 \notag \\
&\overset{(a)}{\leq}
\left( \frac{1 + \rho_W}{2} \right)^k 
\| \mathbf{m}_0^y - \mathbf{1}\bar{m}_0^y \|^2 
+ \frac{nC_{l_y}^2 (1 + \rho_W) \rho_W}{(1 - \rho_W)^2} 
\sum_{t=0}^k 
\left( \frac{1 + \rho_W}{2} \right)^{k-t} \notag \\
&\leq \frac{2nC_{l_y}^2 (1 + \rho_W) \rho_W}{(1 - \rho_W)^2}, \end{align}
where $C_{l_y} = n^2(C_{m^y} + c_0 + d_0(5 \log 2 + c_2))$. The inequality in (a) follows from \cref{Lemma9} and \cref{Lemma11}. Specifically, since $\|\mathbf{h}_0^y\|^2 \leq \|\mathbf{m}_1^y\|^2 \leq \|n \bar{m}_1^y\|^2 \leq n^2(C_{m^y} + c_0 + d_0(5 \log 2 + c_2))$, it follows that the magnitude of the gradient $\|\mathbf{h}_0^y\|$ is upper bounded by $C_{l_y}$.
For $\left\| \mathbf{m}_{k+1}^v-\mathbf{1}\bar{m}_{k+1}^v\right\|^2$, we have:
\begin{align}
&\left\| \mathbf{m}_{k+1}^v-\mathbf{1}\bar{m}_{k+1}^v\right\|^2\notag\\
&\leq\| (W - \mathbf{J}) ( \mathbf{m}_{k}^v-\mathbf{1}\bar{m}_{k}^v)\|^2  +  \|(W - \mathbf{J}) \mathbf{g}_k^v \|^2  \notag \\
&\leq \frac{1 + \rho_W}{2} 
\| \mathbf{m}_k^v - \mathbf{1}\bar{m}_k^v \|^2 
+ \frac{(1 + \rho_W) \rho_W}{1 - \rho_W} \| \mathbf{g}_k^v \|^2 \notag \\
&\overset{(a)}{\leq} 
\left( \frac{1 + \rho_W}{2} \right)^k 
\| \mathbf{m}_0^v - \mathbf{1}\bar{m}_0^v \|^2 
+ \frac{n (1 + \rho_W) \rho_W}{(1 - \rho_W)^2} \left(\frac{C_{l_{yy}}C_{f_y}}{\mu}+C_{f_y}\right)^2
\sum_{t=0}^k 
\left( \frac{1 + \rho_W}{2} \right)^{k-t} \notag \\
&\leq \frac{2n (1 + \rho_W) \rho_W}{(1 - \rho_W)^2}\left(\frac{C_{l_{yy}}C_{f_y}}{\mu}+C_{f_y}\right)^2, \end{align}
where (a) uses \cref{Lemma3}.

At iteration $k$, for the case $\mathbf{m}_k^y \geq \mathbf{m}_k^v$ with $\| \mathbf{m}_0^x\mathbf{m}_0^y - \mathbf{1}\bar{m}_0^x\bar{m}_0^y \|^2 = 0$, we have:
\begin{align}
&\left\| \mathbf{q}_{k+1}-\mathbf{1}\bar{q}_{k+1}\right\|^2=\left\| \mathbf{m}_{k+1}^x\mathbf{m}_{k+1}^y-\mathbf{1}\bar{m}_{k+1}^x\bar{m}_{k+1}^y\right\|^2\notag\\
&\leq\| (W - \mathbf{J}) ( \mathbf{m}_{k}^x\mathbf{m}_{k}^y-\mathbf{1}\bar{m}_{k}^x\bar{m}_{k}^y)\|^2 +  \|(W - \mathbf{J}) \mathbf{g}_k^x\mathbf{g}_k^y \|^2  \notag \\
&\leq \frac{1 + \rho_W}{2} 
\| \mathbf{m}_k^x\mathbf{m}_k^y - \mathbf{1}\bar{m}_k^x\bar{m}_k^y \|^2 
+ \frac{(1 + \rho_W) \rho_W}{1 - \rho_W} \| \mathbf{g}_k^x\mathbf{g}_k^y \|^2 \notag \\
&{\leq} 
\left( \frac{1 + \rho_W}{2} \right)^k 
\| \mathbf{m}_0^x\mathbf{m}_0^y - \mathbf{1}\bar{m}_0^x\bar{m}_0^y \|^2 
\nonumber\\
&\quad+ \frac{nC_{l_y}^2 (1 + \rho_W) \rho_W}{(1 - \rho_W)^2} 
\left(\frac{C_{l_{xy}}C_{f_y}}{\mu}+C_{f_x}\right)^2\sum_{t=0}^k 
\left( \frac{1 + \rho_W}{2} \right)^{k-t} \notag \\
&\leq \frac{2nC_{l_y}^2 (1 + \rho_W) \rho_W}{(1 - \rho_W)^2}\left(\frac{C_{l_{xy}}C_{f_y}}{\mu}+C_{f_x}\right)^2. \end{align}

For the case $\mathbf{m}_k^y < \mathbf{m}_k^v$ with $\| \mathbf{m}_0^x\mathbf{m}_0^v - \mathbf{1}\bar{m}_0^x\bar{m}_0^v\|^2 = 0$, we have:
\begin{align}
&\left\| \mathbf{q}_{k+1}-\mathbf{1}\bar{q}_{k+1}\right\|^2\notag\\
&=\left\| \mathbf{m}_{k+1}^x\mathbf{m}_{k+1}^v-\mathbf{1}\bar{m}_{k+1}^x\bar{m}_{k+1}^v\right\|^2\leq \frac{2n (1 + \rho_W) \rho_W}{(1 - \rho_W)^2}\left(\frac{C_{l_{xy}}C_{f_y}}{\mu}+C_{f_x}\right)^2\left(\frac{C_{l_{yy}}C_{f_y}}{\mu}+C_{f_y}\right)^2\!\!. \end{align}

By summing \cref{eq118} and \cref{eq119}, we obtain the following inequality:
\begin{align}
\left\| \mathbf{q}_{k+1}-\mathbf{1}\bar{q}_{k+1}\right\|^2\leq \frac{2n (1 + \rho_W) \rho_W}{(1 - \rho_W)^2}\left(\frac{C_{l_{xy}}C_{f_y}}{\mu}+C_{f_x}\right)^2\left[C_{l_y}^2+\left(\frac{C_{l_{yy}}C_{f_y}}{\mu}+C_{f_y}\right)^2\right]. \end{align}

Combining \cref{eq120} and \cref{eq114}, we can get the upper bound for $\sum_{k=0}^{t-1} \left\| {\big(\tilde{\mathbf{u}}_{k+1}^{-1}\big)^\top} {\nabla}_y L(\mathbf{x}_k, \mathbf{y}_k) /{n\bar{u}_{k+1}^{-1}}\right\|^2$ in \cref{eq112}. 

Similarly, we have:
\begin{align}
\left\| \mathbf{u}_{k+1}-\mathbf{1}\bar{u}_{k+1}\right\|^2\leq \frac{2nC_{l_y}^2 (1 + \rho_W) \rho_W}{(1 - \rho_W)^2}, \end{align}
and
\begin{align}
\left\| \mathbf{z}_{k+1}-\mathbf{1}\bar{z}_{k+1}\right\|^2\leq \frac{2n (1 + \rho_W) \rho_W}{(1 - \rho_W)^2}\left[C_{l_y}^2+\left(\frac{C_{l_{yy}}C_{f_y}}{\mu}+C_{f_y}\right)^2\right]. \end{align}
Then combine the results in \cref{Lemma11}, we can get the upper bound for $\sum_{k=0}^{t-1} \left\| {\big(\tilde{\mathbf{z}}_{k+1}^{-1}\big)^\top} \nabla_v R(\mathbf{x}_k, \mathbf{y}_k, \mathbf{v}_k) /{n\bar{z}_{k+1}^{-1}}\right\|^2$ in \cref{eq112}.
Thus, the \cref{Lemma12} has been proved.

According to \cref{eq105}, we have:
\begin{align}
&\sum_{k=0}^{t-1} 
\left\|\frac{\big(\tilde{\mathbf{q}}_{k+1}^{-1}\big)^\top}{n\bar{q}_{k+1}^{-1}} \bar{\nabla} F(\mathbf{x}_k, \mathbf{y}_k, \mathbf{v}_k)
\right\|^2 \notag\\
&\leq\frac{1+\zeta_q^2}{n^2\bar{z}_0^2}\left\| \mathbf{q}_{k+1}-\mathbf{1}\bar{q}_{k+1}\right\|^2 \sum_{k=0}^{t-1}\frac{\| \bar{\nabla} F(\mathbf{x}_{k}, \mathbf{y}_{k}, \mathbf{v}_{k}) \|^2}{[\bar{m}^x_{k+1}]^2}\notag \\
&\overset{(a)}{\leq}\frac{(1+\zeta_q^2)(5 \log(t + 1) + c_2)}{n^2\bar{z}_0^2}\left\| \mathbf{q}_{k+1}-\mathbf{1}\bar{q}_{k+1}\right\|^2, \end{align}
where (a) uses \cref{Lemma11}.

For $\left\| \mathbf{m}_{k+1}^y-\mathbf{1}\bar{m}_{k+1}^y\right\|^2$, we have:
\begin{align}
&\left\| \mathbf{m}_{k+1}^y-\mathbf{1}\bar{m}_{k+1}^y\right\|^2\notag\\
&\leq\| (W - \mathbf{J}) ( \mathbf{m}_{k}^y-\mathbf{1}\bar{m}_{k}^y)\|^2 +  \|(W - \mathbf{J}) \mathbf{g}_k^y \|^2  \notag \\
&\leq \frac{1 + \rho_W}{2} 
\| \mathbf{m}_k^y - \mathbf{1}\bar{m}_k^y \|^2 
+ \frac{(1 + \rho_W) \rho_W}{1 - \rho_W} \| \mathbf{g}_k^y \|^2 \notag \\
&\overset{(a)}{\leq}
\left( \frac{1 + \rho_W}{2} \right)^k 
\| \mathbf{m}_0^y - \mathbf{1}\bar{m}_0^y \|^2 
+ \frac{nC_{l_y}^2 (1 + \rho_W) \rho_W}{(1 - \rho_W)^2} 
\sum_{t=0}^k 
\left( \frac{1 + \rho_W}{2} \right)^{k-t} \notag \\
&\leq \frac{2nC_{l_y}^2 (1 + \rho_W) \rho_W}{(1 - \rho_W)^2}, \end{align}
where $C_{l_y} = n^2(C_{m^y} + c_0 + d_0(5 \log 2 + c_2))$. The inequality in (a) follows from \cref{Lemma9} and \cref{Lemma11}. Specifically, since $\|\mathbf{h}_0^y\|^2 \leq \|\mathbf{m}_1^y\|^2 \leq \|n \bar{m}_1^y\|^2 \leq n^2(C_{m^y} + c_0 + d_0(5 \log 2 + c_2))$, it follows that the magnitude of the gradient $\|\mathbf{h}_0^y\|$ is upper bounded by $C_{l_y}$.

At iteration $k$, for the case $\mathbf{m}_k^y \geq \mathbf{m}_k^v$ with $\| \mathbf{m}_0^x\mathbf{m}_0^y - \mathbf{1}\bar{m}_0^x\bar{m}_0^y \|^2 = 0$, we have:
\begin{align}
&\left\| \mathbf{q}_{k+1}-\mathbf{1}\bar{q}_{k+1}\right\|^2=\left\| \mathbf{m}_{k+1}^x\mathbf{m}_{k+1}^y-\mathbf{1}\bar{m}_{k+1}^x\bar{m}_{k+1}^y\right\|^2\notag\\
&\leq\| (W - \mathbf{J}) ( \mathbf{m}_{k}^x\mathbf{m}_{k}^y-\mathbf{1}\bar{m}_{k}^x\bar{m}_{k}^y)\|^2 +  \|(W - \mathbf{J}) \mathbf{g}_k^x\mathbf{g}_k^y \|^2  \notag \\
&\leq \frac{1 + \rho_W}{2} 
\| \mathbf{m}_k^x\mathbf{m}_k^y - \mathbf{1}\bar{m}_k^x\bar{m}_k^y \|^2 
+ \frac{(1 + \rho_W) \rho_W}{1 - \rho_W} \| \mathbf{g}_k^x\mathbf{g}_k^y \|^2 \notag \\
&{\leq} 
\left( \frac{1 + \rho_W}{2} \right)^k 
\| \mathbf{m}_0^x\mathbf{m}_0^y - \mathbf{1}\bar{m}_0^x\bar{m}_0^y \|^2 
\nonumber\\
&\quad+ \frac{nC_{l_y}^2 (1 + \rho_W) \rho_W}{(1 - \rho_W)^2} 
\left(\frac{C_{l_{xy}}C_{f_y}}{\mu}+C_{f_x}\right)^2\sum_{t=0}^k 
\left( \frac{1 + \rho_W}{2} \right)^{k-t} \notag \\
&\leq \frac{2nC_{l_y}^2 (1 + \rho_W) \rho_W}{(1 - \rho_W)^2}\left(\frac{C_{l_{xy}}C_{f_y}}{\mu}+C_{f_x}\right)^2. \end{align}

For the case $\mathbf{m}_k^y < \mathbf{m}_k^v$ with $\| \mathbf{m}_0^x\mathbf{m}_0^v - \mathbf{1}\bar{m}_0^x\bar{m}_0^v\|^2 = 0$, we have:
