  a_7 &:=  \frac{4\bar{L}^2a_6 }{\mu^2\bar{m}^x_{0}}+\frac{2\bar{L}^2a_5}{\mu^2\bar{m}^x_{0}} \left( 1 + \frac{2}{\mu^2} \left( \frac{L_{l,2} C_{f_y}}{\mu} + L_{f,1} \right)^2 \right) \nonumber\\
