&\quad+ \frac{16c_2(1+\zeta_q^2)((1 + \rho_W) \rho_W)}{n\bar{z}_0^2\bar{q}_0(1 - \rho_W)^2}\left(\frac{C_{l_{xy}}C_{f_y}}{\mu}+C_{f_x}\right)^2\left[C_{l_y}^2+\left(\frac{C_{l_{yy}}C_{f_y}}{\mu}+C_{f_y}\right)^2\right] \nonumber\\
&\quad+\frac{4\bar{q}_{0}^{-1}(4\gamma_x \bar{L}_{f}^2L_\Phi \bar{q}_0^{-1} \left(1 +\zeta_q^2\right)+\bar{L}_f^2)}{n}\left(\frac{2 \Delta_0}{1 - \rho_W} 
+ \frac{8c_2 \gamma_x^2 \rho_W (1 + \zeta_q^2)}{(1 - \rho_W)^2}\right. \nonumber \\
&\quad \left.+ \frac{8b_2 \gamma_y^2 \rho_W (1 + \zeta_u^2)}{(1 - \rho_W)^2}+\frac{8 b_3\gamma_v^2 \rho_W (1 + \zeta_z^2)}{(1 - \rho_W)^2}\right)+ \frac{8n\gamma_x C_{m^x}^2 L_\Phi \left(1 +\zeta_q^2\right)}{\bar{q}_0^2}, \end{align}
and the upper bound of $\bar{z}_t := \max\{\bar{m}^y_t, \bar{m}^v_t\}$ refers to \cref{Lemma10}. When such $k_1$ does not exist, we have $\bar{m}^x_t \leq C_{m^x}$ for any $t \leq T$.

