According to \cref{Lemma6}, the proof can be split into the following three cases:

\textbf{Case 1:} If $\bar{m}^x_T \leq C_{m^x}$, for any $t < T$, we have the upper bound of $\bar{m}^x_{t+1}$ as $\bar{m}^x_{t+1} \leq C_{m^x}$.

\textbf{Case 2:} If $\bar{m}^x_T > C_{m^x}$, there exists $k_1 \leq T$ described in \cref{Lemma6}. Then we have the upper bound of $\bar{m}^x_{t+1}$ as $\bar{m}^x_{t+1} \leq C_{m^x}$ for any $t < k_1$.

\textbf{Case 3:} In the remaining proof, we only consider and explore the case $k_1 \leq t \leq T$ when $\bar{m}^x_T > C_{m^x}$.

From \cref{Lemma4}, for $k \geq k_1$, we have:
\begin{align}
&\Phi(\bar{x}_{t+1})\nonumber\\
&\leq\Phi(\bar{x}_t)-\frac{\gamma_x \bar{q}_{t+1}^{-1}}{8}\|\nabla \Phi(\bar{x}_t)\|^2+\frac{\gamma_x\bar{q}_{t+1}^{-1}(2\gamma_x \bar{L}_{f}^2L_\Phi \bar{q}_{t+1}^{-1} \left(1 +\zeta_q^2\right)+\bar{L}_{f}^2)}{n} \Delta_t\nonumber\\
&\quad -\left(\frac{\gamma_x}{2}-{2n\gamma_x^2 L_\Phi \bar{q}_{t+1}^{-1} \left(1 +\zeta_q^2\right)}\right)\frac{\|\nabla_x f(\bar{x}_t, \bar{y}_t, \bar{v}_t)\|^2}{\bar{q}_{t+1}}
+ \frac{\bar{L}^2\gamma_x }{\mu^2} \frac{\|\nabla_v r(\bar{x}_t, \bar{y}_t, \bar{v}_t)\|^2}{\bar{q}_{t+1}} \nonumber \\
&\quad +\!\left(\! \frac{\gamma_x\bar{L}^2}{2\mu^2} \!+\! \frac{\gamma_x\bar{L}^2}{\mu^4}\!\! \left(\! \frac{L_{l,2} C_{f_y}}{\mu} \!+\! L_{f,1} \!\right)^2 \right) \frac{\|\nabla_y l(\bar{x}_t, \bar{y}_t)\|^2}{\bar{q}_{t+1}}\!+\! 2\gamma_x \bar{q}_{t+1}^{-1}  \left\| \frac{\big(\tilde{\mathbf{q}}_{t+1}^{-1}\big)^\top}{n\bar{q}_{t+1}^{-1}} \bar{\nabla} F(\mathbf{x}_t, \mathbf{y}_t, \mathbf{v}_t) \right\|^2\!\!. \end{align}
In addition, if $k_1$ in \cref{Lemma6} exists, then for $t \geq k_1$, we have $\bar{m}^x_{t+1} > C_{m^x} \geq \frac{8n\gamma_x L_\Phi \left(1 +\zeta_q^2\right)}{\bar{z}_0}$ and 
\begin{align}
&\Phi(\bar{x}_{t+1})\nonumber\\
&\leq\Phi(\bar{x}_t)-\frac{\gamma_x \bar{q}_{t+1}^{-1}}{8}\|\nabla \Phi(\bar{x}_t)\|^2+\frac{\gamma_x\bar{q}_{t+1}^{-1}(2\gamma_x \bar{L}_{f}^2L_\Phi \bar{q}_{t+1}^{-1} \left(1 +\zeta_q^2\right)+\bar{L}_{f}^2)}{n} \Delta_t\nonumber\\
&\quad -\frac{\gamma_x }{4}\frac{\|\nabla_x f(\bar{x}_t, \bar{y}_t, \bar{v}_t)\|^2}{\bar{q}_{t+1}}
+ \frac{\bar{L}^2\gamma_x }{\mu^2} \frac{\|\nabla_v r(\bar{x}_t, \bar{y}_t, \bar{v}_t)\|^2}{\bar{q}_{t+1}} \nonumber\\
&\quad+\!\left(\! \frac{\gamma_x\bar{L}^2}{2\mu^2} \!+\! \frac{\gamma_x\bar{L}^2}{\mu^4} \!\!\left(\! \frac{L_{l,2} C_{f_y}}{\mu} + L_{f,1} \!\right)^2 \right)\!\! \frac{\|\nabla_y l(\bar{x}_t, \bar{y}_t)\|^2}{\bar{q}_{t+1}}\!+\! 2\gamma_x \bar{q}_{t+1}^{-1}  \left\| \frac{\big(\tilde{\mathbf{q}}_{t+1}^{-1}\big)^\top}{n\bar{q}_{t+1}^{-1}} \bar{\nabla}F(\mathbf{x}_t, \mathbf{y}_t, \mathbf{v}_t) \right\|^2\!\!, \end{align}
which indicates that
